package com.ethk3.novaonepro.strategyv2;
import java.io.*;
import java.lang.reflect.*;
import java.util.*;

/** Independent joint objectives and numerical derivatives for chain and used-set autoregression. */
public final class R26StructuredDiagnosticsTest {
    static void check(boolean ok,String why){if(!ok)throw new AssertionError(why);}
    static Object field(Object m,String name)throws Exception{Field f=m.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(m);}
    static byte[] save(TemporalModelR26 m)throws IOException{ByteArrayOutputStream b=new ByteArrayOutputStream();m.write(new DataOutputStream(b));return b.toByteArray();}
    static TemporalModelR26 make(String family,int graph,boolean factors){return family.equals("F02")?new FamilyF02KernelR26(graph,factors):new FamilyF18KernelR26();}
    static TemporalModelR26 restore(String family,int graph,boolean factors,byte[] bytes)throws IOException{TemporalModelR26 m=make(family,graph,factors);m.read(new DataInputStream(new ByteArrayInputStream(bytes)));return m;}
    static int[] draw(Random random){int[] d=new int[10];for(int i=0;i<10;i++)d[i]=i+1;for(int i=9;i>0;i--){int q=random.nextInt(i+1),v=d[q];d[q]=d[i];d[i]=v;}return d;}
    static List<double[]> rows(TemporalModelR26 m)throws Exception{List<double[]> rows=new ArrayList<>();for(String name:m instanceof FamilyF02KernelR26?new String[]{"unary","context","pair"}:new String[]{"bias","context","prefix"})append(rows,field(m,name));return rows;}
    static void append(List<double[]> rows,Object array){if(array instanceof double[])rows.add((double[])array);else for(Object child:(Object[])array)append(rows,child);}
    static double[] flat(TemporalModelR26 m)throws Exception{List<double[]> rows=rows(m);double[] all=new double[rows.stream().mapToInt(a->a.length).sum()];int at=0;for(double[] row:rows)for(double value:row)all[at++]=value;return all;}
    static void put(TemporalModelR26 m,double[] values)throws Exception{int at=0;for(double[] row:rows(m))for(int i=0;i<row.length;i++)row[i]=values[at++];}
    static double objective(TemporalModelR26 model,int[] context,int[] target)throws Exception{
        if(model instanceof FamilyF02KernelR26){double[][] u=(double[][])field(model,"unary"),c=(double[][])field(model,"context");double[][][] pairs=(double[][][])field(model,"pair");boolean enabled=(boolean)field(model,"factors");int[] order=(int[])field(model,"order");double[][] scores=new double[10][10];for(int p=0;p<10;p++)for(int n=0;n<10;n++)scores[p][n]=u[p][n]+(context==null?0:c[p*10+n][context[p]-1]);double value=PermutationChainR26.infer(scores,enabled?pairs:new double[9][10][10],order).z;for(int p=0;p<10;p++)value-=scores[p][target[p]-1];if(enabled)for(int p=0;p<9;p++)value-=pairs[p][target[order[p]]-1][target[order[p+1]]-1];return value;}
        double[][] b=(double[][])field(model,"bias"),c=(double[][])field(model,"context"),prefix=(double[][])field(model,"prefix");int mask=0;double loss=0;for(int p=0;p<10;p++){double[] scores=new double[10];double max=Double.NEGATIVE_INFINITY;for(int n=0;n<10;n++)if((mask&(1<<n))==0){scores[n]=b[p][n]+(context==null?0:c[p*10+n][context[p]-1]);if(p>0)for(int used=0;used<10;used++)if((mask&(1<<used))!=0)scores[n]+=prefix[n][used]/p;max=Math.max(max,scores[n]);}double z=0;for(int n=0;n<10;n++)if((mask&(1<<n))==0)z+=Math.exp(scores[n]-max);loss+=max+Math.log(z)-scores[target[p]-1];mask|=1<<(target[p]-1);}return loss;
    }
    public static void main(String[] args)throws Exception{
        double maxError=0;int cases=0;
        for(String family:new String[]{"F02","F18"})for(int graph=0;graph<(family.equals("F02")?3:1);graph++)for(boolean factors:family.equals("F02")?new boolean[]{true,false}:new boolean[]{true}){
            cases++;TemporalModelR26 model=make(family,graph,factors);Random random=new Random(261802+graph);for(int i=0;i<4;i++)model.update(draw(random));double[] old=flat(model);for(int i=0;i<old.length;i++)old[i]=(random.nextDouble()-.5)*.2;put(model,old);int[] context=((int[])field(model,"previous")).clone(),target=draw(random);byte[] prior=save(model);double before=objective(model,context,target);model.update(target);TrainingDiagnosticsR26 measured=(TrainingDiagnosticsR26)model;TrainingDiagnosticsR26.Step step=measured.lastTrainingStep();check(step.update==5&&Math.abs(before-step.lossBefore)<1e-10,"Before joint objective differs");check(Math.abs(objective(model,context,target)-step.lossAfter)<1e-10,"After objective used a revealed lag");double[] after=flat(model),gradient=new double[old.length];double delta=0,norm=0,lr=family.equals("F02")?.02:.03;for(int i=0;i<old.length;i++){check(Math.abs(after[i])<8,"Numerical gradient fixture reached clip");gradient[i]=(old[i]-after[i])/lr;double d=after[i]-old[i];delta+=d*d;norm+=gradient[i]*gradient[i];}check(Math.abs(Math.sqrt(delta)-step.parameterDeltaNorm)<1e-12&&Math.abs(Math.sqrt(norm)-step.gradientNorm)<1e-9,"Actual change/gradient norm differs");
            TemporalModelR26 original=restore(family,graph,factors,prior);for(int trial=0;trial<16;trial++){double[] plus=old.clone(),minus=old.clone();double projection=0,eps=1e-4;for(int i=0;i<old.length;i++){double direction=(random.nextBoolean()?1:-1)/32.0;plus[i]+=eps*direction;minus[i]-=eps*direction;projection+=gradient[i]*direction;}put(original,plus);double upper=objective(original,context,target);put(original,minus);double lower=objective(original,context,target);put(original,old);double error=Math.abs((upper-lower)/(2*eps)-projection);maxError=Math.max(maxError,error);check(error<2e-5,"Joint numerical derivative mismatch: "+family+" "+graph+" "+factors+" "+error);}
            check(Arrays.equals(prior,save(original)),"Oracle mutated original checkpoint");original.update(draw(random));check(step.inputHash.equals(((TrainingDiagnosticsR26)original).lastTrainingStep().inputHash),"Input hash observed target");TemporalModelR26 copy=restore(family,graph,factors,save(model));check(((TrainingDiagnosticsR26)copy).lastTrainingStep()==null,"Restore invented measurement");int[] next=draw(random);model.update(next);copy.update(next);check(Arrays.equals(save(model),save(copy)),"Complete next update differs");long lifetime=measured.completedTrainingUpdates();model.resetTemporalContext();check(measured.completedTrainingUpdates()==lifetime&&measured.lastTrainingStep()==null,"Gap reset learned lifetime");byte[] unchanged=save(model);copy=restore(family,graph,factors,unchanged);next=draw(random);model.update(next);copy.update(next);check(Arrays.equals(save(model),save(copy)),"Gap restore/next update differs");
            unchanged=save(model);byte[] corrupt=unchanged.clone();Arrays.fill(corrupt,corrupt.length-8,corrupt.length,(byte)0xff);try{model.read(new DataInputStream(new ByteArrayInputStream(corrupt)));throw new AssertionError("Nonfinite state restored");}catch(IOException expected){}check(Arrays.equals(unchanged,save(model)),"Rejected restore damaged model");boolean canceled=false;for(int operations:new int[]{1,2,10,100,1000}){model.read(new DataInputStream(new ByteArrayInputStream(unchanged)));ExecutionBudgetR26.enter(new BudgetTokenSU1(30000,operations,()->false));try{model.update(target);}catch(BudgetTokenSU1.Yield expected){canceled=true;check(Arrays.equals(unchanged,save(model))&&((TrainingDiagnosticsR26)model).lastTrainingStep()==null,"Interrupted update changed model");}finally{ExecutionBudgetR26.leave();}}check(canceled,"Cooperative cancellation not observed");
            if(args.length>0&&graph==0&&factors)java.nio.file.Files.write(java.nio.file.Paths.get(args[0],family+"-state-sample.bin"),save(model));
        }
        System.out.println("R26_STRUCTURED_DIAGNOSTICS_PASS|cases="+cases+"|directionalChecks=112|maxDirectionalDerivativeError="+maxError+"|chainAndMaskedAutoregressiveJointObjectives=true|fixedPreLabelLagContext=true|actualGradientAndParameterDelta=true|restoreNextGapCancelAtomic=true|scope=SYNTHETIC_KERNEL_NOT_NATURAL_QUALITY");
    }
}
